/* V25 — animation progressive, interactions réelles et accessibilité */
(()=>{'use strict';const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));const progress=document.createElement('div');progress.id='reading-progress';progress.setAttribute('aria-hidden','true');document.body.prepend(progress);const toast=document.createElement('div');toast.id='toast';toast.setAttribute('role','status');toast.setAttribute('aria-live','polite');document.body.append(toast);let toastTimer;const notify=msg=>{toast.textContent=msg;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3100)};const fx=document.createElement('div');fx.id='celebration';fx.setAttribute('aria-hidden','true');document.body.append(fx);
function burst(x=innerWidth/2,y=innerHeight/2){if(reduce)return;fx.replaceChildren();for(let i=0;i<24;i++){const el=document.createElement('i');el.className='spark';const a=Math.PI*2*i/24,dist=60+Math.random()*145;el.style.setProperty('--sx',x+'px');el.style.setProperty('--sy',y+'px');el.style.setProperty('--dx',Math.cos(a)*dist+'px');el.style.setProperty('--dy',Math.sin(a)*dist+'px');el.style.setProperty('--sc',i%2?'#8B5CF6':'#10B981');fx.append(el)}setTimeout(()=>fx.replaceChildren(),1050)}
let lastScroll=0;function scrollUpdate(){const h=document.documentElement.scrollHeight-innerHeight;progress.style.width=(h>0?Math.min(100,scrollY/h*100):0)+'%';lastScroll=scrollY}addEventListener('scroll',scrollUpdate,{passive:true});scrollUpdate();
if(!reduce&&matchMedia('(pointer:fine)').matches){let frame=false;addEventListener('pointermove',e=>{if(frame)return;frame=true;requestAnimationFrame(()=>{document.body.style.setProperty('--mx',e.clientX+'px');document.body.style.setProperty('--my',e.clientY+'px');frame=false})},{passive:true});$$('.world,.friend,.shortcut').forEach(card=>card.addEventListener('pointermove',e=>{const r=card.getBoundingClientRect();card.style.setProperty('--spot-x',(e.clientX-r.left)+'px');card.style.setProperty('--spot-y',(e.clientY-r.top)+'px')},{passive:true}))}
if(!reduce&&'IntersectionObserver'in window){const io=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');io.unobserve(entry.target)}})},{threshold:.08,rootMargin:'0px 0px -25px 0px'});$$('.section-head,.world,.friend,.social-grid a,.info-panel,.video-frame,.shortcut,.tool,.cta').forEach((el,i)=>{el.classList.add('reveal');el.style.transitionDelay=(i%3)*75+'ms';io.observe(el)})}
if(!reduce)document.addEventListener('pointerdown',e=>{const button=e.target.closest('.btn,.tab,.menu-toggle,.proof-choice,.mini-grid a,.social-grid a');if(!button)return;const rect=button.getBoundingClientRect();const circle=document.createElement('span');circle.className='ripple';const size=Math.max(rect.width,rect.height);circle.style.width=circle.style.height=size+'px';circle.style.left=(e.clientX-rect.left-size/2)+'px';circle.style.top=(e.clientY-rect.top-size/2)+'px';button.append(circle);setTimeout(()=>circle.remove(),700)});
const surprise=$('#surprise-btn');if(surprise)surprise.addEventListener('click',()=>{const options=[{title:'👻 Mission fantômes !',url:'guides.html#phasmo'},{title:'⚔️ Direction Azeroth !',url:'guides.html#wow'},{title:'🎮 On se retrouve en live !',url:'#live'}];const pick=options[Math.floor(Math.random()*options.length)];notify(pick.title+' · Ouverture dans un instant');burst();setTimeout(()=>{location.href=pick.url},850)});
const randomUniverse=$('#random-universe');if(randomUniverse)randomUniverse.addEventListener('click',()=>{const world=$$('.world');if(!world.length)return;const chosen=world[Math.floor(Math.random()*world.length)];chosen.scrollIntoView({behavior:reduce?'auto':'smooth',block:'center'});chosen.style.boxShadow='0 0 0 3px '+(chosen.classList.contains('phasmo')?'#10B981':'#8B5CF6');setTimeout(()=>chosen.style.removeProperty('box-shadow'),2200);notify('🎲 '+(chosen.classList.contains('phasmo')?'Phasmophobia':'World of Warcraft')+' : à toi de jouer !');burst()});
const ghostRandom=$('#random-ghost');if(ghostRandom)ghostRandom.addEventListener('click',()=>{const cards=$$('#ghost-results details');if(!cards.length){notify('Les données des fantômes sont en cours de chargement.');return}const pick=cards[Math.floor(Math.random()*cards.length)];pick.open=true;pick.scrollIntoView({behavior:reduce?'auto':'smooth',block:'center'});notify('👻 '+pick.querySelector('summary').innerText+' : découvre ses indices !');burst()});
const bossRandom=$('#random-boss');if(bossRandom)bossRandom.addEventListener('click',()=>{const cards=$$('#wow-results .boss-item');if(!cards.length){notify('Sélectionne un raid ou un donjon avec des boss disponibles.');return}const pick=cards[Math.floor(Math.random()*cards.length)];pick.open=true;pick.scrollIntoView({behavior:reduce?'auto':'smooth',block:'center'});notify('⚔️ Boss surprise : '+pick.querySelector('summary').textContent);burst()});
for(const [buttonId,selector] of [['toggle-ghosts','#ghost-results details'],['toggle-bosses','#wow-results .boss-item']]){const btn=$('#'+buttonId);if(!btn)continue;btn.addEventListener('click',()=>{const cards=$$(selector);if(!cards.length){notify('Aucune fiche à afficher pour le moment.');return}const open=cards.some(x=>!x.open);cards.forEach(x=>x.open=open);btn.textContent=open?'Tout replier':'Tout déplier';notify(open?'Toutes les fiches sont ouvertes.':'Toutes les fiches sont repliées.')})}
const reset=$('#reset-evidence');if(reset)reset.addEventListener('click',()=>notify('↺ Filtres réinitialisés.'));
const tabs=$$('[data-kind]');tabs.forEach(b=>b.addEventListener('click',()=>{notify(b.dataset.kind==='raids'?'⚔️ Catalogue des raids affiché.':'🏰 Catalogue des donjons affiché.');const toggle=$('#toggle-bosses');if(toggle)toggle.textContent='Tout déplier'}));
$$('a[href^="#"]').forEach(a=>a.addEventListener('click',()=>{const target=document.querySelector(a.getAttribute('href'));if(target&&a.getAttribute('href')!=='#')target.classList.add('target-flash')}));
})();
